    {
        $value = self::filter($request, $name);
        if (null === $value) {
            return null;
        }
        if (1 !== preg_match('/^-?\d+$/', $value)) {
            throw JsonApiException::create(400, 'Invalid parameter', sprintf('filter[%s] must be an integer.', $name), null, 'filter['.$name.']');
