        }
        $value = $source[$key];
        if (!is_string($value) || 1 !== preg_match('/^\d+$/', $value)) {
            throw JsonApiException::create(400, 'Invalid parameter', sprintf('%s must be an integer.', $parameter), null, $parameter);
